use vstd::prelude::*;

verus! {

// Specification function to check if a number is even
spec fn is_even(x: i32) -> bool {
    x % 2 == 0
}

// Specification function to check if a value exists in a slice
spec fn contains(s: Seq<i32>, val: i32) -> bool {
    exists|i: int| 0 <= i < s.len() && s[i] == val
}

// Specification function to check if all elements in result are even and from input
spec fn all_even_and_from_input(input: Seq<i32>, result: Seq<i32>) -> bool {
    forall|i: int| 0 <= i < result.len() ==> 
        is_even(result[i]) && contains(input, result[i])
}

// Specification function to check if all even elements from input are in result
spec fn all_input_evens_in_result(input: Seq<i32>, result: Seq<i32>) -> bool {
    forall|i: int| 0 <= i < input.len() && is_even(input[i]) ==> 
        contains(result, input[i])
}

fn remove_odd_numbers(arr: &[i32]) -> (result: Vec<i32>)
    ensures
        all_even_and_from_input(arr@, result@),
        all_input_evens_in_result(arr@, result@),
{
    let mut result: Vec<i32> = Vec::new();
    let mut idx: usize = 0;
    
    while idx < arr.len()
        invariant
            idx <= arr.len(),
            all_even_and_from_input(arr@, result@),
            forall|i: int| 0 <= i < idx && is_even(arr@[i]) ==> 
                contains(result@, arr@[i]),
    {
        let val = arr[idx];
        if val % 2 == 0 {
            result.push(val);
            assert(contains(arr@, val));
        }
        idx = idx + 1;
    }
    
    result
}

} // verus!

